// VFA: Parse Results from Playwright stdout

// 1) stdout aus Execute Command holen
if (!items[0] || !items[0].json || typeof items[0].json.stdout !== 'string') {
  throw new Error('Parse Results: stdout missing or not a string');
}

const stdout = items[0].json.stdout;

// 2) stdout als JSON parsen (oder null, wenn komplett kaputt)
let output = null;
try {
  output = JSON.parse(stdout);
} catch (e) {
  output = null;
}

// 3) ursprüngliche URL aus Trigger holen
let originalInput = {};
try {
  originalInput = $items('When Executed by Another Workflow', 0, 0).json || {};
} catch (e) {
  originalInput = {};
}

const fallbackUrl =
  (output && (output.url || output.pageUrl)) ||
  originalInput.url ||
  originalInput.pageUrl ||
  'unbekannte URL';

// 4) Fallback, wenn Playwright-Output keine results enthält
if (
  !output ||
  !output.results ||
  !Array.isArray(output.results) ||
  output.results.length === 0
) {
  // Kein verwertbares Ergebnis → trotzdem ein Item zurückgeben,
  // damit der Workflow weiterläuft und der Report sagen kann,
  // dass VFA hier nichts Sinnvolles liefern konnte.
  return [
    {
      json: {
        url: fallbackUrl,
        selector: null,
        role: null,
        width: null,
        height: null,
        viewport: '',
        wcag: '2.4.11 Focus Not Obscured (Minimum)',
        issue:
          'Playwright-VFA konnte keine auswertbaren Ergebnisse liefern (kein results-Array im Output).',
        stdout_truncated: typeof stdout === 'string' ? stdout.slice(0, 2000) : '',
        precheck_no_targets: true,
        parse_error:
          !output ? 'stdout_not_valid_json_or_unexpected_shape' : 'no_results_array',
      },
    },
  ];
}

// 5) Normalfall: wir haben results
const run = output.results[0];
const screenshotBase64 = run.screenshot || null;

const runUrl =
  output.url ||
  run.url ||
  fallbackUrl;

const viewportText = run.viewport
  ? `${run.viewport.width}x${run.viewport.height}`
  : '';

const failedTargets = [];

// Targets durchsuchen und nur die problematischen zurückgeben
if (Array.isArray(run.targets)) {
  for (const target of run.targets) {
    if (!target.pass) {
      failedTargets.push({
        url: runUrl,
        selector: target.selector || '',
        role: target.role || '',
        width: target.width ?? null,
        height: target.height ?? null,
        viewport: viewportText,
        wcag: '2.4.11 Focus Not Obscured (Minimum)',
        issue: 'Element might be obscured when focused',
        screenshot: screenshotBase64,
      });
    }
  }
}

// 6) Wenn keine verdächtigen Targets → trotzdem ein Item zurückgeben
if (failedTargets.length === 0) {
  return [
    {
      json: {
        url: runUrl,
        selector: null,
        role: null,
        width: null,
        height: null,
        viewport: viewportText,
        wcag: '2.4.11 Focus Not Obscured (Minimum)',
        issue: 'Pre-Check hat keine potenziell verdeckten Fokusziele gefunden.',
        screenshot: screenshotBase64,
        precheck_no_targets: true,
      },
    },
  ];
}

// 7) Sonst: pro failed Target ein Item
return failedTargets.map(t => ({ json: t }));

const basePrompt = `
Rolle:
Du bist ein Accessibility-Experte und bewertest das WCAG-2.4.11-Kriterium
"Focus Not Obscured (Minimum)" für ein einzelnes Fokusziel.

Kontext:
- URL: ${$json.url || 'unbekannte URL'}
- CSS-Selector: ${$json.selector || 'unbekannt'}
- ARIA-Rolle: ${$json.role || 'unbekannt'}
- Viewport: ${$json.viewport || 'unbekannt'}
- Detektierter Befund (Vorprüfung): ${$json.issue || 'keine Angabe'}

Aufgabe:
1. Prüfe, ob das fokussierte Element im (ggf. bereitgestellten) Screenshot vollständig sichtbar ist
   oder teilweise / vollständig von anderen Inhalten verdeckt wird.
2. Beschreibe in knapper Form die Ursache, falls es verdeckt wird (z. B. Sticky-Header, Overlay, Modal).
3. Triff eine klare Bewertung, ob WCAG 2.4.11 erfüllt ist oder nicht.

Wenn kein brauchbarer Screenshot vorliegt oder das Element nicht zuverlässig erkannt werden kann:
- Setze "is_violation" auf null.
- Schreibe eine kurze, sachliche Begründung im Feld "summary", z. B.
  "Das fokussierte Element konnte im Screenshot nicht sicher identifiziert werden; Bewertung ist unklar."
- Gib KEINE allgemeinen Testanleitungen und keine langen Schritt-für-Schritt-Anweisungen zurück.

WICHTIG:
- Antworte ausschließlich auf DEUTSCH.
- Gib ausschließlich gültiges JSON ohne erklärenden Fließtext zurück.
- Verwende genau dieses Format:

{
  "url": "<erkannte URL oder leer>",
  "is_violation": true | false | null,
  "severity": "low" | "medium" | "high" | null,
  "summary": "<kurze Zusammenfassung auf Deutsch>",
  "reasons": ["<kurze Begründung 1>", "<Begründung 2>"],
  "evidence": ["<Hinweise auf konkrete Stellen, z. B. Sticky-Header verdeckt Fokus>"]
}
`.trim();

// Screenshot aus Parse Results
const screenshot = $json.screenshot;

// Content-Array für die OpenAI-Anfrage
const content = [
  {
    type: 'text',
    text: basePrompt,
  },
];

// Screenshot nur anhängen, wenn er tatsächlich wie Base64 aussieht
if (typeof screenshot === 'string') {
  const trimmed = screenshot.trim();

  let dataUrl = null;

  // Fall 1: bereits data:-URL
  if (trimmed.startsWith('data:image')) {
    dataUrl = trimmed;
  } else {
    // Fall 2: reiner Base64-Blob
    const base64Candidate = trimmed.replace(/\s+/g, '');
    const looksLikeBase64 =
      /^[A-Za-z0-9+/=]+$/.test(base64Candidate) && base64Candidate.length > 100;

    if (looksLikeBase64) {
      dataUrl = `data:image/png;base64,${base64Candidate}`;
    }
  }

  if (dataUrl) {
    content.push({
      type: 'image_url',
      image_url: {
        url: dataUrl,
        detail: 'auto',
      },
    });
  }
}

// Request-Body für HTTP Request Node
return {
  json: {
    body: {
      model: 'gpt-4o',
      max_tokens: 400,
      messages: [
        {
          role: 'user',
          content,
        },
      ],
    },
  },
};

// VFA: Build Report (Aggregation aller geprüften Elemente)

const items = $input.all(); // Alle Ergebnisse vom LLM (HTTP Request)
const firstItem = items[0] || {};

// Metadaten aus dem ersten Item holen (URL ist bei allen gleich)
// Wir versuchen, die URL aus dem AI-Response oder dem Kontext zu retten
let url = 'unbekannte URL';

// Ergebnisse sammeln
const detailedResults = [];
let violationCount = 0;
let preCheckNoTargets = false;

// Durch alle Items (geprüfte Elemente) iterieren
for (const item of items) {
    const raw = item.json || {};

    // 1. Content vom LLM parsen
    let content = raw;
    if (raw.choices && raw.choices[0]?.message?.content) {
        content = raw.choices[0].message.content.trim();
    }

    let analysis = {};
    if (typeof content === 'string') {
        const cleanContent = content.replace(/```json/g, '').replace(/```/g, '').trim();
        try {
            analysis = JSON.parse(cleanContent);
        } catch (e) {
            analysis = { summary: "Fehler beim Parsen der KI-Antwort", is_violation: null };
        }
    } else {
        analysis = content;
    }

    // URL retten (falls vorhanden)
    if (!url || url === 'unbekannte URL') {
        if (analysis.url) url = analysis.url;
    }

    // 2. Prüfen: War das ein "Keine Targets" Durchlauf?
    // (Das müssten wir idealerweise aus dem vorherigen Node durchschleifen, 
    // aber oft erkennt man es am leeren Analysis-Ergebnis oder spezifischen Text)
    if (analysis.summary && analysis.summary.includes('keine potenziell verdeckten Fokusziele')) {
        preCheckNoTargets = true;
        continue; 
    }

    // 3. Violation prüfen
    if (analysis.is_violation === true) {
        violationCount++;
        detailedResults.push({
            issue_id: "2.4.11-focus-not-obscured",
            // Da wir den Selektor hier evtl. verloren haben (wenn er nicht im LLM Output ist),
            // nutzen wir die Beschreibung als Identifier
            description: analysis.summary || "Fokus-Indikator ist verdeckt.",
            severity: analysis.severity || "serious",
            tool: "gpt-4o-vision",
            count: 1,
            evidence: analysis.evidence ? analysis.evidence.join('; ') : "Screenshot Analyse",
            recommendation: "Ensure element is fully visible when focused (e.g. adjust scroll padding)."
        });
    }
}

// Gesamtstatus bestimmen
let status = 'pass';
let executiveSummary = '';

if (preCheckNoTargets && violationCount === 0) {
    status = 'pass';
    executiveSummary = "Der Vorab-Check (Playwright) hat keine potenziell verdeckten Elemente gefunden. Visuelle Prüfung unauffällig.";
} else if (violationCount > 0) {
    status = 'fail';
    executiveSummary = `Die visuelle KI-Analyse hat ${violationCount} Elemente identifiziert, bei denen der Fokus-Indikator verdeckt oder nicht sichtbar ist (WCAG 2.4.11).`;
} else {
    status = 'pass';
    executiveSummary = "Alle geprüften Fokus-Ziele waren visuell frei zugänglich. Keine Verstöße gegen WCAG 2.4.11 erkannt.";
}

const reportMarkdown = `## VFA Report (WCAG 2.4.11)\nStatus: ${status}\n\n${executiveSummary}\n\nGefundene Verstöße: ${violationCount}`;

return [
  {
    json: {
      agent_name: "VFA",
      wcag_criterion: "2.4.11",
      status: status,
      executive_summary: executiveSummary,
      detailed_results: detailedResults,
      url: url,
      reportMarkdown: reportMarkdown,
    },
    binary: firstItem.binary 
  }
];

const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

function sanitize(text) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/\u202F/g, ' ');
  t = t
    .split('')
    .map(ch => (ch.charCodeAt(0) > 255 ? ' ' : ch))
    .join('');
  return t;
}

async function run() {
  const item = items[0];
  const data = item.json || {};
  const binary = item.binary || {};

  const url = sanitize(data.url || 'unbekannte URL');
  const wcagArr = Array.isArray(data.wcag) ? data.wcag : (data.wcag ? [data.wcag] : []);
  const wcagText = wcagArr.length ? wcagArr.join(', ') : '2.4.11';
  const resultRaw = (data.result || 'unknown').toLowerCase();
  const summary = sanitize(data.summary || '');
  const md = sanitize(data.reportMarkdown || '');

  const pdfDoc = await PDFDocument.create();
  let page = pdfDoc.addPage();
  const { width, height } = page.getSize();

  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let cursorY = height - 40;

  function colorForResult() {
    switch (resultRaw) {
      case 'fail':
      case 'error':
        return rgb(0.8, 0, 0);
      case 'warning':
      case 'partial':
        return rgb(0.9, 0.5, 0);
      case 'pass':
        return rgb(0, 0.5, 0);
      default:
        return rgb(0, 0, 0);
    }
  }

  function wrapText(page, text, x, y, opts = {}) {
    const font = opts.font || fontRegular;
    const size = opts.size || 11;
    const color = opts.color || rgb(0, 0, 0);
    const maxWidth = opts.maxWidth || (width - 80);
    const lineHeight = opts.lineHeight || (size + 3);

    const words = text.split(/\s+/);
    let line = '';

    for (const w of words) {
      const testLine = line ? line + ' ' + w : w;
      const lineWidth = font.widthOfTextAtSize(testLine, size);
      if (lineWidth > maxWidth) {
        page.drawText(line, { x, y, size, font, color });
        y -= lineHeight;
        line = w;
      } else {
        line = testLine;
      }
    }

    if (line) {
      page.drawText(line, { x, y, size, font, color });
      y -= lineHeight;
    }

    return y;
  }

  function ensureSpace(linesNeeded, baseSize = 11) {
    const minY = 40;
    const estimated = baseSize + 4;
    if (cursorY - linesNeeded * estimated < minY) {
      page = pdfDoc.addPage();
      cursorY = height - 40;
    }
  }

  // Titelzeile
  ensureSpace(2, 16);
  page.drawText('VFA-Agent Bericht   Fokus nicht verdeckt (WCAG 2.4.11)', {
    x: 40,
    y: cursorY,
    size: 16,
    font: fontBold,
    color: rgb(0, 0, 0),
  });
  cursorY -= 24;

  // Meta: URL, WCAG, Ergebnis
  ensureSpace(3, 11);
  cursorY = wrapText(page, `URL: ${url}`, 40, cursorY, { font: fontRegular, size: 11 });
  cursorY = wrapText(page, `WCAG: ${wcagText}`, 40, cursorY, { font: fontRegular, size: 11 });
  cursorY = wrapText(
    page,
    `Ergebnis: ${resultRaw.toUpperCase()}`,
    40,
    cursorY,
    { font: fontBold, size: 11, color: colorForResult() }
  );
  cursorY -= 10;

  // Zusammenfassung
  if (summary) {
    ensureSpace(3, 12);
    page.drawText('Kurzfassung', {
      x: 40,
      y: cursorY,
      size: 13,
      font: fontBold,
      color: rgb(0, 0, 0),
    });
    cursorY -= 18;
    cursorY = wrapText(page, summary, 40, cursorY, { font: fontRegular, size: 11 });
    cursorY -= 10;
  }

  // Markdown-Body
  if (md) {
    ensureSpace(2, 12);
    page.drawText('Detailanalyse', {
      x: 40,
      y: cursorY,
      size: 13,
      font: fontBold,
      color: rgb(0, 0, 0),
    });
    cursorY -= 18;

    const lines = md.split(/\r?\n/);
    for (let rawLine of lines) {
      const line = rawLine.trimEnd();

      if (!line.trim()) {
        cursorY -= 6;
        continue;
      }

      // Überschriften: #, ##, ###
      const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
      if (headingMatch) {
        const level = headingMatch[1].length;
        const text = headingMatch[2];
        const size = level === 1 ? 14 : level === 2 ? 13 : 12;
        ensureSpace(2, size);
        cursorY = wrapText(page, text, 40, cursorY, {
          font: fontBold,
          size,
        });
        cursorY -= 4;
        continue;
      }

      // Bullet-Listen: - oder *
      const bulletMatch = line.match(/^\s*[-*]\s+(.*)$/);
      if (bulletMatch) {
        const text = '• ' + bulletMatch[1];
        ensureSpace(1, 11);
        cursorY = wrapText(page, text, 50, cursorY, {
          font: fontRegular,
          size: 11,
        });
        continue;
      }

      // normaler Absatz
      ensureSpace(2, 11);
      cursorY = wrapText(page, line, 40, cursorY, {
        font: fontRegular,
        size: 11,
      });
    }
  }

  const pdfBytes = await pdfDoc.save();
  const pdfBase64 = Buffer.from(pdfBytes).toString('base64');

  return [
    {
      json: data,
      binary: {
        report: {
          data: pdfBase64,
          mimeType: 'application/pdf',
          fileName: 'vfa-agent-report.pdf',
        },
        ...(binary.screenshot ? { screenshot: binary.screenshot } : {}),
      },
    },
  ];
}

return run();

const inputItem = $input.first().json;

return {
  json: {
    agent_name: inputItem.agent_name || "VFA",
    wcag_criterion: inputItem.wcag_criterion,
    status: inputItem.status,
    executive_summary: inputItem.executive_summary,
    detailed_results: inputItem.detailed_results,
    // Kein PDF Link, da für Manager irrelevant
  }
};
